def check_expression(expression):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')

    for char in expression:
        if char in opening:
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False
        else:
            continue

    return len(stack) == 0
```

