def check_expression(exp):
    if len(exp) & 1:
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in exp:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
```

